ks","siteText","rating","value"]}},"lead":{"separator":" | ","parts":["{{n}}. {{name}}","type: {{type}}","Google reviews: {{reviews}}","website: {{website}}","contact: {{contact}}","checks: {{checks}}","site text: {{siteText}}"],"words":{"ratingSuffix":" (rating {{rating}})","noWebsite":"none found","phone":"phone","email":"email","social":"social page","noSiteText":"none","quoted":"\"{{value}}\""}}}};
// Prompt text lives in prompts/<name>/ in the repository and is embedded here. render() fills {{variables}}
// and stops with a clear error when one is missing, instead of sending a broken prompt to the AI.
const render = (template, vars) => String(template).replace(/\{\{(\w+)\}\}/g, (m, k) => {
  if (!Object.prototype.hasOwnProperty.call(vars, k)) throw new Error('prompt variable missing: ' + k + ' (' + PROMPTS.version + ')');
  return String(vars[k]);
});
// One AI call per search: the best leads, the freelancer's offer and only facts we collected.
// The text, the wording of each lead line and the limits live in prompts/fit/ (PROMPTS, with render(), is put in front of this code).
const body = $('Webhook').first().json.body || {};
const leads = $input.all().map(i => i.json);
const picks = leads.map((l, i) => [l, i]).filter(([l]) => l && l.aiCheck);
if (!picks.length) return [{ json: { prompt: null, idx: [] } }];

const LIM = PROMPTS.data.config.limits;
const LEAD = PROMPTS.data.lead;
const W = LEAD.words;
const clean = (t, n = LIM.text) => String(t || '').replace(/[\r\n]+/g, ' ').replace(/[<>{}\[\]]/g, ' ').slice(0, n);
const host = u => String(u || '').replace(/^https?:\/\//, '').split('/')[0];

const lines = picks.map(([l], k) => {
  const vars = {
    n: k + 1,
    name: clean(l.name).slice(0, LIM.name),
    type: clean(l.niche).slice(0, LIM.niche),
    reviews: (l.reviews || 0) + (l.rating ? render(W.ratingSuffix, { rating: l.rating }) : ''),
    website: l.website ? host(l.website) : W.noWebsite,
    contact: [l.phone ? W.phone : '', (l.emails || []).length ? W.email : '', (l.social || []).length ? W.social : ''].filter(Boolean).join(', '),
    checks: clean(l.reason).slice(0, LIM.checks),
    siteText: l.siteText ? render(W.quoted, { value: clean(l.siteText) }) : W.noSiteText,
  };
  return LEAD.parts.map(part => render(part, vars)).join(LEAD.separator);
});

const prompt = render(PROMPTS.templates.prompt, { service: clean(body.service).slice(0, LIM.service), leads: lines.join('\n') });
return [{ json: { prompt, idx: picks.map(([, i]) => i), promptVersion: PROMPTS.version } }];

// The AI fit weighs more than the rules for the checked leads. Without an answer, the rule score stays.
const leads = $('Score').all().map(i => ({ ...i.json }));
const idx = $('AI Prompt').first().json.idx || [];
let results = [];
try {
  const r = $input.first().json || {};
  const raw = (r.candidates && r.candidates[0].content.parts.map(p => p.text || '').join('')) || '';
  const o = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  results = Array.isArray(o.results) ? o.results : [];
} catch (e) { results = []; }
const tidy = t => String(t || '').replace(/\[\[|\]\]/g, '').replace(/\s+/g, ' ').trim().slice(0, 90);
for (const res of results) {
  const i = idx[(Number(res.k) || 0) - 1];
  const l = i === undefined ? null : leads[i];
  const fit = Math.round(Number(res.fit));
  if (!l || !(fit >= 1 && fit <= 10)) continue;
  l.score = Math.max(1, Math.min(10, Math.round(0.5 * l.score + 0.5 * fit)));
  const en = tidy(res.why_en), fr = tidy(res.why_fr);
  const sig = ['gap', 'pain', 'neglect', 'momentum'].includes(res.signal) ? res.signal : '';
  // a note that reuses a word of the rule checks says the same thing twice: keep only the group
  const words = t => (String(t).toLowerCase().match(/[a-zà-ÿ]{4,}/g) || []);
  const known = new Set(words(l.reason));
  const repeats = words(en).some(w => known.has(w));
  if (en && !repeats) l.reason = l.reason + ' AI: ' + en + (fr ? ' [[fr:' + fr + ']]' : '') + (sig ? ' [[sig:' + sig + ']]' : '');
  else if (sig) l.reason = l.reason + ' [[sig:' + sig + ']]';
}
return leads.map(json => ({ json }));

const jobId = $('Webhook').first().json.body.jobId;
const out = $input.all().map(i => i.json).filter(l => !l._empty).map(l => {
  const r = { ...l, subject: '', emailBody: '' };
  for (const k of ['niche', 'city', 'service', 'sender', 'hasBooking', 'siteChecked', 'fetchUrl', 'audit', 'lookedUp', 'siteText', 'aiCheck']) delete r[k];
  return r;
});
out.sort((a, b) => {
  const aReachable = Boolean(a.phone || (a.emails && a.emails.length) || (a.social && a.social.length));
  const bReachable = Boolean(b.phone || (b.emails && b.emails.length) || (b.social && b.social.length));
  if (aReachable !== bReachable) return bReachable ? 1 : -1;
  return b.score - a.score;
});
// A drawn rectangle has no name: use the town that appears most in the addresses ("..., Tunis 2092, Tunisia").
let areaName = null;
if ($('Webhook').first().json.body.bbox) {
  const towns = {};
  for (const l of out) {
    const parts = String(l.address || '').split(',').map(x => x.replace(/\d+/g, '').trim()).filter(Boolean);
    const town = parts.length >= 2 ? parts[parts.length - 2] : null;
    if (town && town.length <= 40) towns[town] = (towns[town] || 0) + 1;
  }
  const best = Object.entries(towns).sort((a, b) => b[1] - a[1])[0];
  areaName = best ? best[0].replace(/[\[\]]/g, '') : null;
}
return [{ json: { jobId, leads: out, areaName } }];

const webhookBody = $('Webhook').first().json.body || {};
// The backend sends the admin's chat id only for the admin's own searches; nothing to send otherwise.
if (!webhookBody.alertChatId) return [];
const input = $input.first().json || {};
const leads = input.leads || [];

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const niche = esc(webhookBody.niche || 'N/A');
const location = esc(webhookBody.city || (webhookBody.bbox ? 'Map Bounding Box' : 'N/A'));
const total = leads.length;
const reachable = leads.filter(l => Boolean(l.phone || (l.emails && l.emails.length) || (l.social && l.social.length))).length;

let html = '🎯 <b>Leadforge Alert: New Leads Discovered!</b>\n\n';
html += '📍 <b>Niche:</b> ' + niche + '\n';
html += '🌍 <b>Location:</b> ' + location + '\n';
html += '📊 <b>Found:</b> ' + total + ' leads (' + reachable + ' reachable)\n\n';

if (leads.length > 0) {
  html += '🔥 <b>Top Opportunities:</b>\n';
  const top = leads.slice(0, 3);
  top.forEach((l, idx) => {
    const contact = esc(l.phone || (l.emails && l.emails[0]) || (l.website ? 'Website listed' : 'No contact found'));
    html += (idx + 1) + '. <b>' + esc(l.name || 'Unnamed') + '</b> (Score: ' + (l.score || 0) + '/10)\n   📞 ' + contact + '\n';
  });
} else {
  html += '⚠️ <i>No leads were found for this search.</i>';
}

return [{ json: { chatId: String(webhookBody.alertChatId), text: html } }];
